html:
{#- Vehicle Certificate (Traceability): identity, configuration, build, final inspection and warranty of one vehicle. A4, black on white. -#}
{%- macro esc(value) -%}{%- if value is defined and value is not none -%}{{ value|e }}{%- endif -%}{%- endmacro -%}
{%- macro num(value) -%}
{%- set n = frappe.utils.flt(value) -%}
{%- if n == frappe.utils.cint(n) -%}{{ frappe.utils.fmt_money(n, 0) }}{%- else -%}{{ frappe.format(n, {"fieldtype": "Float"}) }}{%- endif -%}
{%- endmacro -%}
{%- set model = frappe.db.get_value("Vehicle Model", doc.vehicle_model, ["model_name", "product_family"], as_dict=True) if doc.vehicle_model else none -%}
{%- set variant_name = frappe.db.get_value("Item", doc.variant_item, "item_name") if doc.variant_item else none -%}
{%- if doc.configuration -%}
{%- set options = frappe.get_all("Vehicle Configuration Selection", filters={"parent": doc.configuration, "parenttype": "Vehicle Configuration"}, fields=["attribute", "attribute_value"], order_by="idx asc") -%}
{%- elif doc.variant_item -%}
{%- set options = frappe.get_all("Item Variant Attribute", filters={"parent": doc.variant_item, "parenttype": "Item"}, fields=["attribute", "attribute_value"], order_by="idx asc") -%}
{%- else -%}
{%- set options = [] -%}
{%- endif -%}
{%- set inspection = frappe.db.get_value("Quality Inspection", doc.final_inspection, ["status", "inspected_by", "report_date"], as_dict=True) if doc.final_inspection else none -%}
<style>
	@page { size: A4; margin: 15mm; }
	.hn-doc { color: #000; background: #fff; font-size: 9pt; line-height: 1.35; }
	.hn-doc table { width: 100%; border-collapse: collapse; }
	.hn-doc th, .hn-doc td { color: #000; background: #fff; border: 1px solid #000; padding: 1.2mm 1.8mm; text-align: left; vertical-align: top; }
	.hn-doc .hn-head { margin-bottom: 4mm; border-bottom: 0.6mm solid #000; }
	.hn-doc .hn-head td { border: 0; padding: 0 0 2mm 0; vertical-align: bottom; }
	.hn-doc .hn-company { font-size: 10pt; font-weight: bold; }
	.hn-doc .hn-title { font-size: 16pt; font-weight: bold; margin-top: 1mm; }
	.hn-doc .hn-right { text-align: right; }
	.hn-doc .hn-label { font-size: 7.5pt; }
	.hn-doc .hn-docno { font-size: 12pt; font-weight: bold; font-family: monospace; }
	.hn-doc .hn-state { display: inline-block; margin-top: 1mm; padding: 0.5mm 2mm; border: 0.5mm solid #000; font-weight: bold; }
	.hn-doc .hn-meta th { width: 18%; }
	.hn-doc .hn-meta td { width: 32%; }
	.hn-doc .hn-section { margin: 5mm 0 1.5mm 0; font-size: 10.5pt; font-weight: bold; }
	.hn-doc .hn-lines { margin-top: 4mm; }
	.hn-doc .hn-lines thead { display: table-header-group; }
	.hn-doc .hn-lines th { border-bottom: 0.5mm solid #000; }
	.hn-doc .hn-lines tr, .hn-doc .hn-sign, .hn-doc .hn-avoid { page-break-inside: avoid; break-inside: avoid; }
	.hn-doc .hn-num { text-align: right; white-space: nowrap; }
	.hn-doc .hn-strong { font-weight: bold; }
	.hn-doc .hn-mono { font-family: monospace; }
	.hn-doc .hn-summary { margin-top: 2mm; text-align: right; }
	.hn-doc .hn-vin { font-family: monospace; font-size: 20pt; font-weight: bold; letter-spacing: 1px; }
	.hn-doc .hn-vin-box { margin-bottom: 2mm; padding: 2mm 3mm; border: 0.6mm solid #000; }
</style>
<div class="hn-doc">
	<table class="hn-head">
		<tr>
			<td>
				<div class="hn-company">{{ esc(doc.company) }}</div>
				<div class="hn-title">{{ _("Vehicle Certificate") }}</div>
			</td>
		</tr>
	</table>
	<div class="hn-vin-box">
		<div class="hn-label">{{ _("VIN") }}</div>
		<div class="hn-vin">{{ esc(doc.vin) }}</div>
	</div>

	<div class="hn-section">{{ _("Vehicle") }}</div>
	<table class="hn-meta hn-avoid">
		<tr>
			<th>{{ _("Vehicle Model") }}</th>
			<td>{{ esc(model.model_name) if model else "" }} ({{ esc(doc.vehicle_model) }})</td>
			<th>{{ _("Product Family") }}</th>
			<td>{{ _(model.product_family) if model and model.product_family else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Variant") }}</th>
			<td>{{ esc(doc.variant_item) }}{% if variant_name and variant_name != doc.variant_item %}<br>{{ esc(variant_name) }}{% endif %}</td>
			<th>{{ _("Configuration") }}</th>
			<td>{{ esc(doc.configuration) }}</td>
		</tr>
		{%- for option in options %}
		<tr>
			<th>{{ esc(option.attribute) }}</th>
			<td colspan="3" class="hn-strong">{{ esc(option.attribute_value) }}</td>
		</tr>
		{%- endfor %}
	</table>

	<div class="hn-section">{{ _("Build") }}</div>
	<table class="hn-meta hn-avoid">
		<tr>
			<th>{{ _("Build Date") }}</th>
			<td class="hn-strong">{{ frappe.format(frappe.utils.getdate(doc.built_at), {"fieldtype": "Date"}) if doc.built_at else "" }}</td>
			<th>{{ _("Build Plant") }}</th>
			<td class="hn-strong">{{ esc(frappe.db.get_value("Plant", doc.plant, "plant_name") or doc.plant) if doc.plant else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Production Line") }}</th>
			<td>{{ esc(frappe.db.get_value("Production Line", doc.production_line, "line_name") or doc.production_line) if doc.production_line else "" }}</td>
			<th>{{ _("Work Order") }}</th>
			<td>{{ esc(doc.work_order) }}</td>
		</tr>
	</table>

	<div class="hn-section">{{ _("Final Inspection") }}</div>
	<table class="hn-meta hn-avoid">
		<tr>
			<th>{{ _("Result") }}</th>
			<td class="hn-strong">{{ _(inspection.status) if inspection and inspection.status else "" }}</td>
			<th>{{ _("Quality Release") }}</th>
			<td class="hn-strong">{{ _(doc.quality_status) if doc.quality_status else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Inspector") }}</th>
			<td>{{ esc(frappe.get_fullname(inspection.inspected_by)) if inspection and inspection.inspected_by else "" }}</td>
			<th>{{ _("Inspection Date") }}</th>
			<td>{{ frappe.format(inspection.report_date, {"fieldtype": "Date"}) if inspection and inspection.report_date else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Quality Inspection") }}</th>
			<td colspan="3">{{ esc(doc.final_inspection) }}</td>
		</tr>
	</table>

	<div class="hn-section">{{ _("Warranty") }}</div>
	<table class="hn-meta hn-avoid">
		<tr>
			<th>{{ _("Warranty Start") }}</th>
			<td class="hn-strong">{{ doc.get_formatted("warranty_start_date") if doc.warranty_start_date else _("Starts on delivery acceptance") }}</td>
			<th>{{ _("Warranty End") }}</th>
			<td class="hn-strong">{{ doc.get_formatted("warranty_end_date") if doc.warranty_end_date else "" }}</td>
		</tr>
		<tr>
			<th>{{ _("Warranty Reference") }}</th>
			<td colspan="3">{{ esc(doc.warranty_reference) }}</td>
		</tr>
	</table>
</div>
